def dividir(a, b):
    if b == 0:
        raise ZeroDivisionError("Divisor não pode ser zero")
    return a / b

exercises.test_code:
assert dividir(6, 2) == 3.0, 'dividir(6, 2) deveria ser 3.0'
try:
    dividir(6, 0)
    raise AssertionError('dividir(6, 0) deveria ter levantado ZeroDivisionError')
except ZeroDivisionError:
    pass

